const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Needles, CA and Phoenix, AZ (points with 5km buffers)
  const needles = ee.Geometry.Point([-114.6141, 34.8381]).buffer(5000);
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]).buffer(5000);

  // Date for June 21, 2017
  const startDate = '2017-06-21';
  const endDate = '2017-06-22';

  // 2. Load MODIS LST collection (MOD11A1.061)
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day']);

  // 3. Check data availability
  const collSize = modisLST.size().getInfo();
  console.log(`MODIS Images: ${collSize}`);

  if (collSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Get the image and process LST
  const image = modisLST.first();

  // Convert LST from Kelvin to Celsius (scale = 0.02, then -273.15)
  const lst = image.select('LST_Day_1km')
    .multiply(0.02)
    .subtract(273.15);

  // Use QC band to mask poor quality (bits 0-1: 00=good, bits 2-3: 00=good)
  const qc = image.select('QC_Day');
  const mask = qc.bitwiseAnd(parseInt('1111', 2)).eq(0);
  const lstMasked = lst.updateMask(mask);

  // 5. Calculate statistics for both locations
  const needlesStats = lstMasked.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: needles,
    scale: 1000,
    maxPixels: 1e9
  });

  const phoenixStats = lstMasked.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: phoenix,
    scale: 1000,
    maxPixels: 1e9
  });

  const needlesMean = needlesStats.get('LST_Day_1km').getInfo();
  const needlesCount = needlesStats.get('LST_Day_1km_count').getInfo();
  const phoenixMean = phoenixStats.get('LST_Day_1km').getInfo();
  const phoenixCount = phoenixStats.get('LST_Day_1km_count').getInfo();

  console.log(`Needles LST: ${needlesMean?.toFixed(2)}°C, Pixels: ${needlesCount}`);
  console.log(`Phoenix LST: ${phoenixMean?.toFixed(2)}°C, Pixels: ${phoenixCount}`);

  // 6. Validate results
  if (needlesCount === 0 || phoenixCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (needlesMean === null || phoenixMean === null || 
      isNaN(needlesMean) || isNaN(phoenixMean) ||
      needlesMean < -100 || needlesMean > 100 ||
      phoenixMean < -100 || phoenixMean > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare temperatures and output answer
  if (needlesMean > phoenixMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
